    /**
     * Performs an INSERT on the database, given a ServicioAnexos or Criteria object.
     *
     * @param      mixed $values Criteria or ServicioAnexos object containing data that is used to create the INSERT statement.
     * @param      PropelPDO $con the PropelPDO connection to use
     * @return mixed           The new primary key.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doInsert($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(ServicioAnexosPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity
        } else {
            $criteria = $values->buildCriteria(); // build Criteria from ServicioAnexos object
        }

        if ($criteria->containsKey(ServicioAnexosPeer::SERVICIOANEXOS_ID) && $criteria->keyContainsValue(ServicioAnexosPeer::SERVICIOANEXOS_ID) ) {
            throw new PropelException('Cannot insert a value for auto-increment primary key ('.ServicioAnexosPeer::SERVICIOANEXOS_ID.')');
        }

        // remove pkey col since this table uses auto-increment and passing a null value for it is not valid
        $criteria->remove(ServicioAnexosPeer::SERVICIOANEXOS_ID);


        // Set the correct dbName
        $criteria->setDbName(ServicioAnexosPeer::DATABASE_NAME);

        try {
            // use transaction because $criteria could contain info
            // for more than one table (I guess, conceivably)
            $con->beginTransaction();
            $pk = BasePeer::doInsert($criteria, $con);
            $con->commit();
        } catch (Exception $e) {
            $con->rollBack();
            throw $e;
        }

        return $pk;
    }

