    public static function doUpdate($values, PropelPDO $con = null)
    {
        if ($con === null) {
            $con = Propel::getConnection(ServicioAnexosPeer::DATABASE_NAME, Propel::CONNECTION_WRITE);
        }

        $selectCriteria = new Criteria(ServicioAnexosPeer::DATABASE_NAME);

        if ($values instanceof Criteria) {
            $criteria = clone $values; // rename for clarity

            $comparison = $criteria->getComparison(ServicioAnexosPeer::SERVICIOANEXOS_ID);
            $value = $criteria->remove(ServicioAnexosPeer::SERVICIOANEXOS_ID);
            if ($value) {
                $selectCriteria->add(ServicioAnexosPeer::SERVICIOANEXOS_ID, $value, $comparison);
            } else {
                $selectCriteria->setPrimaryTableName(ServicioAnexosPeer::TABLE_NAME);
            }

        } else { // $values is ServicioAnexos object
            $criteria = $values->buildCriteria(); // gets full criteria
            $selectCriteria = $values->buildPkeyCriteria(); // gets criteria w/ primary key(s)
        }

        // set the correct dbName
        $criteria->setDbName(ServicioAnexosPeer::DATABASE_NAME);

        return BasePeer::doUpdate($selectCriteria, $criteria, $con);
    }

    /**
     * Deletes all rows from the SERVICIO_ANEXOS table.
     *
     * @param      PropelPDO $con the connection to use
     * @return int             The number of affected rows (if supported by underlying database driver).
